var t=[{title:`Előnyök és az engedély`,text:`Az ACOG azt tanácsolja, hogy a szövődménymentes terhességgel rendelkezők közül sokan folytathatnak vagy kezdhetnek megfelelő aerob és erőnléti mozgást. Beszélj a mozgásról a szülészeti ellátásodat nyújtó egészségügyi szakemberrel, különösen, ha új rutint kezdesz, vagy szövődményeid vannak. Ő meg tudja mondani, hogy a terhességed orvosilag szövődménymentes-e. A TrainUp nem tudja.`},{title:`Alkalmazkodj a változásokhoz`,text:`Az egyensúlyod, a hőtűrésed, a légzési komfortod és a kedvelt mozdulataid a terhesség során változhatnak. Kényelmes tevékenységeket válassz. Kerüld a túlmelegedést, az esés vagy ütközés valódi kockázatával járó tevékenységeket és a szédülést okozó testhelyzeteket. Ha korábban sokat mozogtál, klinikai útmutatással megtarthatsz bizonyos megterhelő tevékenységet, mert a terhesség nem jelent automatikusan teljes pihenést.`},{title:`Figyelmeztető jelek`,text:`Hagyd abba a mozgást, és fordulj szülészeti klinikusodhoz, ha hüvelyi vérzésed, folyadékszivárgásod, mellkasi fájdalmad, szédülésed, vádlifájdalmad vagy duzzanatod, fájdalmas összehúzódásaid vagy szokatlan légszomjad van. A sürgősségi tünetek azonnali ellátást igényelnek. Ne próbáld meg a terhességspecifikus tüneteket gyakorlatcserékkel kikerülni.`},{title:`Szülés után`,text:`Hogy mikor térhetsz vissza a mozgáshoz, az a szüléstől, a felépülésedtől, a kismedencei tünetektől és más személyes tényezőktől függ. Egyeseknek a könnyű séta rendben lehet. A tartós fájdalom, szivárgás, nehézségérzet vagy más problémák szakmai felülvizsgálatot igényelnek, és nincs mindenkire érvényes fix időrend. A TrainUp nem készít terhességi, kismedencei vagy műtét utáni programokat.`}];var a=[{label:`ACOG: mozgás terhesség alatt`,url:`https://www.acog.org/womens-health/faqs/exercise-during-pregnancy`},{label:`ACOG: mozgás terhesség alatt és szülés után`,url:`https://www.acog.org/clinical/clinical-guidance/committee-opinion/articles/2020/04/physical-activity-and-exercise-during-pregnancy-and-the-postpartum-period`}];var l={sections:t,sources:a};export{l as default,t as sections,a as sources};